SELECT COUNT(*)
  FROM customer
 WHERE login_id = #{loginId}

SELECT COUNT(*)
  FROM customer
 WHERE email = #{email}

SELECT id, login_id, password, name, email, is_withdrawn AS withdrawn
  FROM customer
 WHERE login_id = #{loginId}

SELECT id, password, is_withdrawn AS withdrawn
  FROM customer
 WHERE id = #{id}

mapper.update:
UPDATE customer
   SET password = #{newPasswordHash}
 WHERE id = #{id}

UPDATE customer
   SET is_withdrawn = TRUE
 WHERE id = #{id}
